SELECT m.chembl_id AS chembl_id, m.pref_name AS pref_name, cs.canonical_smiles AS canonical_smiles, di.efo_id AS indication_curie, di.efo_term AS indication_label, di.max_phase_for_ind AS max_phase_for_ind FROM molecule_dictionary m LEFT JOIN compound_structures cs ON cs.molregno = m.molregno JOIN drug_indication di ON di.molregno = m.molregno WHERE m.therapeutic_flag = 1 AND di.max_phase_for_ind = 4 AND di.efo_term = 'chronic kidney disease' ORDER BY m.chembl_id, m.pref_name, cs.canonical_smiles, di.efo_id, di.efo_term, di.max_phase_for_ind;
